program_source = '''from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]

    runs = []
    for horizontal in (True, False):
        outer = h if horizontal else w
        inner = w if horizontal else h
        for fixed in range(outer):
            i = 0
            while i < inner:
                def cell(pos):
                    return grid[fixed][pos] if horizontal else grid[pos][fixed]
                if cell(i) == background:
                    i += 1
                    continue
                start = i
                values = []
                while i < inner and cell(i) != background:
                    values.append(cell(i))
                    i += 1
                if len(values) >= 3 and len(set(values)) > 1:
                    runs.append((len(values), horizontal, fixed, start, values))
    if not runs:
        return [row[:] for row in grid]
    _, horizontal, fixed, start, pattern = max(runs)
    n = len(pattern)
    out = [row[:] for row in grid]

    # Each symmetric three-cell pattern marks the center for a copy.
    outer = h if horizontal else w
    inner = w if horizontal else h
    for line in range(outer):
        for center in range(1, inner - 1):
            def cell(pos):
                return grid[line][pos] if horizontal else grid[pos][line]
            a, b, c = cell(center - 1), cell(center), cell(center + 1)
            if a == c and a != b and (a != background or b != background):
                begin = center - n // 2
                if begin < 0 or begin + n > inner:
                    continue
                for offset, value in enumerate(pattern):
                    if horizontal:
                        out[line][begin + offset] = value
                    else:
                        out[begin + offset][line] = value
    return out
'''
